Local Ltac pchk_merge c k HK :=
  lazymatch goal with
  | |- aevtA ?segs _ _ (MS ?R ?F (if ?cnd then Z_to_bv 64 ?slow else Z_to_bv 64 ?fast) ?fc ?rv ?m ?ro) =>
